<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/helpers.php';
require_once __DIR__ . '/config/database.php';
require_login();
if (current_role() !== 'guru') { http_response_code(403); exit('Halaman ini hanya untuk akun guru.'); }
$link = $pdo->prepare('SELECT role,guru_id,aktif FROM users WHERE id=?'); $link->execute([(int)$_SESSION['user_id']]); $account = $link->fetch();
if (!$account || $account['role'] !== 'guru' || (int)$account['aktif'] !== 1) { http_response_code(403); exit('Akun guru tidak aktif atau perannya telah berubah. Silakan masuk kembali.'); }
$teacherId = (int)($account['guru_id'] ?? 0);
if ($teacherId < 1) { http_response_code(403); exit('Akun belum ditautkan ke data guru. Hubungi Super Admin sekolah.'); }
$q = $pdo->prepare('SELECT id,nama,nip,status FROM guru WHERE id=?'); $q->execute([$teacherId]); $teacher = $q->fetch();
if (!$teacher) { http_response_code(404); exit('Data guru tertaut tidak ditemukan.'); }
$assignStmt = $pdo->prepare('SELECT DISTINCT j.kelas_id,j.mapel_id,j.tahun_ajaran_id,k.nama_kelas,m.nama_mapel,ta.nama AS tahun_ajaran FROM jadwal_pelajaran j JOIN kelas k ON k.id=j.kelas_id JOIN mapel m ON m.id=j.mapel_id JOIN tahun_ajaran ta ON ta.id=j.tahun_ajaran_id WHERE j.guru_id=? AND ta.aktif=1 ORDER BY k.nama_kelas,m.nama_mapel');
$assignStmt->execute([$teacherId]); $assignments = $assignStmt->fetchAll();
$view = (string)($_GET['view'] ?? 'dashboard');
if (!in_array($view, ['dashboard','jadwal','kelas','rencana','absensi','nilai'], true)) $view = 'dashboard';
$error = ''; $success = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $view = (string)($_POST['view'] ?? 'dashboard');
    try {
        if ($view === 'absensi' && ($_POST['action'] ?? '') === 'save_absensi') {
            $classId = (int)($_POST['kelas_id'] ?? 0); $date = (string)($_POST['tanggal'] ?? '');
            $parsed = DateTimeImmutable::createFromFormat('!Y-m-d', $date);
            if (!$parsed || $parsed->format('Y-m-d') !== $date || $date > date('Y-m-d')) throw new InvalidArgumentException('Tanggal absensi harus valid dan tidak boleh di masa depan.');
            $assigned = array_filter($assignments, static fn($a) => (int)$a['kelas_id'] === $classId);
            if (!$assigned) throw new InvalidArgumentException('Kelas ini bukan bagian dari jadwal aktif Anda.');
            $rosterQuery = $pdo->prepare("SELECT id FROM siswa WHERE kelas_id=? AND status='Aktif' ORDER BY nama"); $rosterQuery->execute([$classId]); $studentIds = array_map('intval', $rosterQuery->fetchAll(PDO::FETCH_COLUMN));
            $posted = $_POST['status_siswa'] ?? [];
            if (!$studentIds || !is_array($posted)) throw new InvalidArgumentException('Tidak ada siswa aktif atau data absensi tidak valid.');
            $pdo->beginTransaction();
            $save = $pdo->prepare('INSERT INTO absensi (siswa_id,tanggal,status,keterangan) VALUES (?,?,?,NULL) ON DUPLICATE KEY UPDATE status=VALUES(status)');
            foreach ($studentIds as $sid) { $status = (string)($posted[$sid] ?? ''); if (!in_array($status, ['Hadir','Izin','Sakit','Alpa'], true)) throw new InvalidArgumentException('Pilih status absensi yang valid untuk setiap siswa.'); $save->execute([$sid,$date,$status]); }
            $pdo->commit(); record_activity($pdo, 'input absensi kelas', 'absensi', null, 'Guru '.$teacherId.' · kelas '.$classId.' · '.$date); $success = 'Absensi kelas berhasil disimpan.';
        } elseif ($view === 'nilai' && ($_POST['action'] ?? '') === 'save_nilai') {
            $classId=(int)($_POST['kelas_id']??0); $mapelId=(int)($_POST['mapel_id']??0); $yearId=(int)($_POST['tahun_ajaran_id']??0); $semester=(string)($_POST['semester']??'');
            $authorized=false; foreach($assignments as $a) if((int)$a['kelas_id']===$classId&&(int)$a['mapel_id']===$mapelId&&(int)$a['tahun_ajaran_id']===$yearId)$authorized=true;
            if(!$authorized||!in_array($semester,['1','2'],true)) throw new InvalidArgumentException('Kelas, mata pelajaran, tahun ajaran, atau semester bukan bagian dari jadwal aktif Anda.');
            $rosterQuery=$pdo->prepare("SELECT id FROM siswa WHERE kelas_id=? AND status='Aktif' ORDER BY nama");$rosterQuery->execute([$classId]);$studentIds=array_map('intval',$rosterQuery->fetchAll(PDO::FETCH_COLUMN));
            $tugas=$_POST['tugas']??[];$uts=$_POST['uts']??[];$uas=$_POST['uas']??[];
            if(!$studentIds||!is_array($tugas)||!is_array($uts)||!is_array($uas)) throw new InvalidArgumentException('Daftar nilai tidak valid.');
            $pdo->beginTransaction();$save=$pdo->prepare('INSERT INTO nilai (siswa_id,mapel_id,tahun_ajaran_id,semester,nilai_tugas,nilai_uts,nilai_uas,nilai_ujian) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE nilai_tugas=VALUES(nilai_tugas),nilai_uts=VALUES(nilai_uts),nilai_uas=VALUES(nilai_uas),nilai_ujian=VALUES(nilai_ujian)');
            foreach($studentIds as $sid){$scores=[(string)($tugas[$sid]??''),(string)($uts[$sid]??''),(string)($uas[$sid]??'')];foreach($scores as $score)if($score===''||!is_numeric($score)||(float)$score<0||(float)$score>100)throw new InvalidArgumentException('Isi nilai Tugas, UTS, dan UAS setiap siswa dengan angka 0 sampai 100.');$save->execute([$sid,$mapelId,$yearId,$semester,(float)$scores[0],(float)$scores[1],(float)$scores[2],(float)$scores[2]]);}
            $pdo->commit();record_activity($pdo,'input nilai kelas','nilai',null,'Guru '.$teacherId.' · kelas '.$classId.' · mapel '.$mapelId);$success='Nilai kelas berhasil disimpan.';
        }
    } catch (Throwable $e) { if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Data gagal disimpan. Periksa penugasan, lalu coba kembali.'; }
}
$view = in_array($view,['dashboard','jadwal','kelas','rencana','absensi','nilai'],true)?$view:'dashboard';
$pageTitle = match($view){'jadwal'=>'Jadwal Mengajar','kelas'=>'Kelas Saya','rencana'=>'Rencana Ajar','absensi'=>'Input Absensi Kelas','nilai'=>'Input Nilai Kelas',default=>'Dashboard Guru'};
$rows=[];$sql=match($view){
 'jadwal'=>"SELECT j.hari,j.jam_mulai,j.jam_selesai,k.nama_kelas,m.nama_mapel,j.ruang FROM jadwal_pelajaran j JOIN kelas k ON k.id=j.kelas_id JOIN mapel m ON m.id=j.mapel_id WHERE j.guru_id=? ORDER BY FIELD(j.hari,'Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'),j.jam_mulai",
 'kelas'=>'SELECT DISTINCT k.id,k.nama_kelas,ta.nama AS tahun_ajaran FROM kelas k JOIN jadwal_pelajaran j ON j.kelas_id=k.id JOIN tahun_ajaran ta ON ta.id=k.tahun_ajaran_id WHERE j.guru_id=? UNION SELECT k.id,k.nama_kelas,ta.nama AS tahun_ajaran FROM kelas_binaan kb JOIN kelas k ON k.id=kb.kelas_id JOIN tahun_ajaran ta ON ta.id=kb.tahun_ajaran_id WHERE kb.guru_id=? ORDER BY nama_kelas',
 'rencana'=>'SELECT ra.judul,ra.semester,ra.status,k.nama_kelas,m.nama_mapel,ta.nama AS tahun_ajaran FROM rencana_ajar ra JOIN kelas k ON k.id=ra.kelas_id JOIN mapel m ON m.id=ra.mapel_id JOIN tahun_ajaran ta ON ta.id=ra.tahun_ajaran_id WHERE ra.guru_id=? ORDER BY ta.nama DESC,ra.semester',default=>''};
if($sql!==''){$q=$pdo->prepare($sql);$q->execute($view==='kelas'?[$teacherId,$teacherId]:[$teacherId]);$rows=$q->fetchAll();}
$classes=[];foreach($assignments as $a)$classes[(int)$a['kelas_id']]=$a['nama_kelas'];
$assignmentParts=explode('|',(string)($_GET['assignment']??''));
$selectedClass=(int)($_POST['kelas_id']??$_GET['kelas_id']??$assignmentParts[0]??0);if(!isset($classes[$selectedClass]))$selectedClass=(int)(array_key_first($classes)??0);
$date=(string)($_POST['tanggal']??$_GET['tanggal']??date('Y-m-d'));
$selectedMapel=(int)($_POST['mapel_id']??$_GET['mapel_id']??$assignmentParts[1]??0);$selectedYear=(int)($_POST['tahun_ajaran_id']??$_GET['tahun_ajaran_id']??$assignmentParts[2]??0);$selectedSemester=(string)($_POST['semester']??$_GET['semester']??'1');
$validAssignment=null;foreach($assignments as $a)if((int)$a['kelas_id']===$selectedClass&&(int)$a['mapel_id']===$selectedMapel&&(int)$a['tahun_ajaran_id']===$selectedYear)$validAssignment=$a;
if(!$validAssignment&&$assignments){$validAssignment=$assignments[0];$selectedClass=(int)$validAssignment['kelas_id'];$selectedMapel=(int)$validAssignment['mapel_id'];$selectedYear=(int)$validAssignment['tahun_ajaran_id'];}
$roster=[];if(in_array($view,['absensi','nilai'],true)&&$selectedClass>0){
 if($view==='absensi'){$q=$pdo->prepare("SELECT s.id,s.nis,s.nama,a.status FROM siswa s LEFT JOIN absensi a ON a.siswa_id=s.id AND a.tanggal=? WHERE s.kelas_id=? AND s.status='Aktif' ORDER BY s.nama");$q->execute([$date,$selectedClass]);$roster=$q->fetchAll();}
 elseif($validAssignment){$q=$pdo->prepare("SELECT s.id,s.nis,s.nama,n.nilai_tugas,n.nilai_uts,n.nilai_uas FROM siswa s LEFT JOIN nilai n ON n.siswa_id=s.id AND n.mapel_id=? AND n.tahun_ajaran_id=? AND n.semester=? WHERE s.kelas_id=? AND s.status='Aktif' ORDER BY s.nama");$q->execute([$selectedMapel,$selectedYear,$selectedSemester,$selectedClass]);$roster=$q->fetchAll();}
 if($_SERVER['REQUEST_METHOD']==='POST'&&$error!=='')foreach($roster as &$studentRow){$sid=(int)$studentRow['id'];if($view==='absensi')$studentRow['status']=$_POST['status_siswa'][$sid]??$studentRow['status'];else{$studentRow['nilai_tugas']=$_POST['tugas'][$sid]??$studentRow['nilai_tugas'];$studentRow['nilai_uts']=$_POST['uts'][$sid]??$studentRow['nilai_uts'];$studentRow['nilai_uas']=$_POST['uas'][$sid]??$studentRow['nilai_uas'];}}unset($studentRow);
}
require __DIR__.'/includes/header.php'; ?>
<div class="dashboard-heading"><div><h1><?= e($pageTitle) ?></h1><p>Informasi dan catatan pembelajaran untuk <?= e($teacher['nama']) ?>, dibatasi pada jadwal penugasan aktif.</p></div></div>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?>
<div class="row g-3 mb-4"><div class="col-md-6"><div class="card p-3"><small class="text-secondary">Guru</small><strong><?= e($teacher['nama']) ?></strong></div></div><div class="col-md-6"><div class="card p-3"><small class="text-secondary">NIP</small><strong><?= e($teacher['nip']?:'Belum diisi') ?></strong></div></div></div>
<?php if($view==='dashboard'): ?><div class="row g-3"><div class="col-md-4"><a class="card p-4 d-block text-decoration-none h-100" href="teacher.php?view=jadwal"><h2 class="h5">Jadwal Mengajar</h2><p class="text-secondary mb-0">Jadwal yang ditugaskan kepada Anda.</p></a></div><div class="col-md-4"><a class="card p-4 d-block text-decoration-none h-100" href="teacher.php?view=kelas"><h2 class="h5">Kelas Saya</h2><p class="text-secondary mb-0">Kelas dari jadwal dan pembinaan Anda.</p></a></div><div class="col-md-4"><a class="card p-4 d-block text-decoration-none h-100" href="teacher.php?view=rencana"><h2 class="h5">Rencana Ajar</h2><p class="text-secondary mb-0">Rencana ajar milik Anda.</p></a></div><div class="col-md-6"><a class="card p-4 d-block text-decoration-none h-100" href="teacher.php?view=absensi"><h2 class="h5">Input Absensi</h2><p class="text-secondary mb-0">Catat kehadiran hanya untuk siswa di kelas terjadwal Anda.</p></a></div><div class="col-md-6"><a class="card p-4 d-block text-decoration-none h-100" href="teacher.php?view=nilai"><h2 class="h5">Input Nilai</h2><p class="text-secondary mb-0">Kelola nilai untuk mata pelajaran dan kelas terjadwal Anda.</p></a></div></div>
<?php elseif($view==='absensi'): ?><div class="card p-3 p-md-4"><form method="get" class="row g-3 mb-3"><input type="hidden" name="view" value="absensi"><div class="col-md-6"><label class="form-label">Kelas</label><select class="form-select" name="kelas_id"><?php foreach($classes as $id=>$name): ?><option value="<?= (int)$id ?>" <?= $selectedClass===(int)$id?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Tanggal</label><input class="form-control" type="date" name="tanggal" value="<?= e($date) ?>" max="<?= date('Y-m-d') ?>" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-outline-primary">Tampilkan</button></div></form><?php if(!$classes): ?><div class="alert alert-info">Belum ada kelas dan jadwal aktif yang ditugaskan kepada akun Anda.</div><?php elseif($roster): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_absensi"><input type="hidden" name="view" value="absensi"><input type="hidden" name="kelas_id" value="<?= $selectedClass ?>"><input type="hidden" name="tanggal" value="<?= e($date) ?>"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>NIS</th><th>Nama Siswa</th><th>Status Kehadiran</th></tr></thead><tbody><?php foreach($roster as $s): ?><tr><td><?= e($s['nis']) ?></td><td><?= e($s['nama']) ?></td><td><select class="form-select" name="status_siswa[<?= (int)$s['id'] ?>]" required><?php foreach(['Hadir','Izin','Sakit','Alpa'] as $status): ?><option value="<?= $status ?>" <?= ($s['status']??'Hadir')===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select></td></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-primary">Simpan Absensi</button></form><?php else: ?><div class="empty-state">Tidak ada siswa aktif di kelas ini.</div><?php endif; ?></div>
<?php elseif($view==='nilai'): ?><div class="card p-3 p-md-4"><form method="get" class="row g-3 mb-3"><input type="hidden" name="view" value="nilai"><div class="col-md-6"><label class="form-label">Kelas dan Mata Pelajaran</label><select class="form-select" name="assignment" required><option value="">Pilih penugasan</option><?php foreach($assignments as $a): ?><option value="<?= (int)$a['kelas_id'].'|'.(int)$a['mapel_id'].'|'.(int)$a['tahun_ajaran_id'] ?>" <?= $validAssignment && (int)$a['kelas_id']===$selectedClass&&(int)$a['mapel_id']===$selectedMapel&&(int)$a['tahun_ajaran_id']===$selectedYear?'selected':'' ?>><?= e($a['nama_kelas'].' · '.$a['nama_mapel'].' · '.$a['tahun_ajaran']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Semester</label><select class="form-select" name="semester"><option value="1" <?= $selectedSemester==='1'?'selected':'' ?>>Ganjil</option><option value="2" <?= $selectedSemester==='2'?'selected':'' ?>>Genap</option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-outline-primary">Tampilkan</button></div></form><?php if(!$validAssignment): ?><div class="alert alert-info">Belum ada penugasan kelas dan mata pelajaran pada tahun ajaran aktif.</div><?php elseif($roster): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_nilai"><input type="hidden" name="view" value="nilai"><input type="hidden" name="kelas_id" value="<?= $selectedClass ?>"><input type="hidden" name="mapel_id" value="<?= $selectedMapel ?>"><input type="hidden" name="tahun_ajaran_id" value="<?= $selectedYear ?>"><input type="hidden" name="semester" value="<?= e($selectedSemester) ?>"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>NIS</th><th>Nama</th><th>Tugas</th><th>UTS</th><th>UAS</th></tr></thead><tbody><?php foreach($roster as $s): ?><tr><td><?= e($s['nis']) ?></td><td><?= e($s['nama']) ?></td><?php foreach(['nilai_tugas'=>'tugas','nilai_uts'=>'uts','nilai_uas'=>'uas'] as $col=>$name): ?><td><input class="form-control" type="number" name="<?= $name ?>[<?= (int)$s['id'] ?>]" min="0" max="100" step="0.01" value="<?= e($s[$col]??'') ?>" required></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-primary">Simpan Nilai</button><p class="form-text mt-2 mb-0">Nilai hanya dapat disimpan untuk siswa aktif pada kelas dan mata pelajaran yang ditugaskan kepada Anda.</p></form><?php else: ?><div class="empty-state">Belum ada siswa aktif pada kelas ini.</div><?php endif; ?></div>
<?php else: ?><div class="card p-3"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><?php foreach(array_keys($rows[0]??[]) as $col): ?><th><?= e(field_label((string)$col)) ?></th><?php endforeach; ?></tr></thead><tbody><?php if(!$rows): ?><tr><td class="text-center text-secondary">Belum ada data yang terkait dengan akun ini.</td></tr><?php else: foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?= e($value) ?></td><?php endforeach; ?></tr><?php endforeach; endif; ?></tbody></table></div></div><?php endif; ?>
<?php require __DIR__.'/includes/footer.php'; ?>
